\ir helpers/private-schema-assertions.psql

begin;

set local search_path = pg_catalog, extensions, public;

select no_plan();

select has_function(
  'vortex_access', 'permission_record_scope_is_valid', array['jsonb'],
  'Access has one private record-scope shape validator'
);

select is(
  (
    select pg_catalog.jsonb_build_object(
      'owner', owner_role.rolname,
      'securityDefiner', routine.prosecdef,
      'volatility', routine.provolatile,
      'configuration', routine.proconfig,
      'result', pg_catalog.pg_get_function_result(routine.oid)
    )
    from pg_catalog.pg_proc as routine
    join pg_catalog.pg_roles as owner_role on owner_role.oid = routine.proowner
    where routine.oid =
      'vortex_access.permission_record_scope_is_valid(jsonb)'::regprocedure
  ),
  pg_catalog.jsonb_build_object(
    'owner', 'postgres',
    'securityDefiner', false,
    'volatility', 'i',
    'configuration', array['search_path=""'],
    'result', 'boolean'
  ),
  'the record-scope validator is owner-held, immutable, invoker-rights and empty-search-path'
);

select ok(
  not pg_catalog.has_function_privilege(
    caller.role_name,
    'vortex_access.permission_record_scope_is_valid(jsonb)',
    'EXECUTE'
  ),
  caller.role_name || ' cannot call the private record-scope validator'
)
from (values
  ('public'), ('anon'), ('authenticated'), ('service_role'),
  ('vortex_runtime'), ('vortex_request')
) as caller(role_name)
order by caller.role_name collate "C";

-- Shared record-scope parity corpus (#387 review finding B1). Extends the
-- original 36-vector corpus with an independently-built 106-vector probe
-- (scratchpad/review-45-387/B-parity/make-corpus.mjs) verified against both
-- the real Zod schema and the pre-fix store, plus 12 new vectors adding an
-- absent and a JSON-null vector for every required field at every level
-- (routes; route objects incl. relationship's two id fields; the
-- savedCondition envelope's four keys; each binding's key/source/value).
-- Six vectors the reviewer's probe found disagreeing for reasons unrelated
-- to B1 are intentionally excluded -- known, accepted divergences, listed in
-- the commit and PR report: the all-F UUID (SQL stricter than Zod for
-- relationshipId, sourcePermissionId and conditionId), a publishedRevision
-- spelled 1.0 or 10e-1 (SQL's canonical-integer-text regex is stricter than
-- Zod's parsed-number check), and a binding's literal value 1e400 (Zod's
-- jsonValueSchema requires a finite number; SQL does not constrain an
-- opaque literal value's content, and jsonb's arbitrary-precision numeric
-- storage never overflows to Infinity the way the JSON.parse'd JS number
-- does).
create temporary table record_scope_corpus on commit drop as
select $record_scope_vectors$
